    tree = etree.parse(svg_path)
    root = tree.getroot()

    svg_h = 1080.0
    vb = root.get("viewBox", "")
    if vb:
        parts = vb.split()
        if len(parts) == 4:
            try:
                svg_h = float(parts[3])
            except ValueError:
                pass

    textboxes = _extract_textboxes(root)
    if not textboxes:
        print(f"  No text found in foreignObject, copying as-is")

    # Remove all foreignObject elements
    removed = 0

