    const rectA = elemA.getBoundingClientRect();
    const rectB = elemB.getBoundingClientRect();
    const overlapRect = getOverlapRect(rectA, rectB);
    if (!overlapRect) return false;

    // 创建离屏 canvas，尺寸为重叠区域大小
    const canvas = document.createElement('canvas');
    canvas.width = overlapRect.width;
    canvas.height = overlapRect.height;
    const ctx = canvas.getContext('2d');

